```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

struct Node;

impl Guest for Node {
    fn run(composed: Digest) -> PublishedDigest {
        let message = format!("{}: {}", composed.date, composed.overview);
        let published = crate::aap::caps::notifier::notify(&message);

        PublishedDigest {
            date: composed.date,
            considered: composed.considered,
            published,
        }
    }
}

export!(Node);
